            break;
        case 'Ethereum':
            contentDiv.innerHTML = '<p style="display: block;">You can only send <b>Ethereum, Binance Coin, USDT or BUSDT</b> to this address. Sending other coin might result in loss of your coin</p><b>Selected Network: Ethereum (ERC20) or Binance (BEP20)</b><br><br><br><div class="input-container">Your Wallet Address: &nbsp;&nbsp;&nbsp;&nbsp;<input type="text" readonly="" style="width: 49%;" value="0x6E79813Abf11FDACdE29c66891bDc245A75309Fa"><button class="copy-btn" onclick="copyToClipboard(this)">Copy 📋</button></div><br><div style="text-align: center;"><img style="height: 200px;" src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=0x6E79813Abf11FDACdE29c66891bDc245A75309Fa"></div><br><br>Please copy the address or scan QR and send equivalent amount of coin with given network to this address.';
            break;
        case 'Binance':
            contentDiv.innerHTML = 'Binance payment details...';
            break;
        case 'Doge':
            contentDiv.innerHTML = 'Doge payment details...';
            break;
        default:
            contentDiv.style.display = "none"; // Hide the div if no valid option is selected
            break;
    }
});
function copyToClipboard(btn) {
    const input = btn.previousElementSibling;
    input.select();
    document.execCommand("copy");
}

window.onload = function() {
    document.getElementById('network').value = "";
};

    </script>
